  <style>
    :root {
      --primary: #7FD1AE;
      --ink: #1D2B33;
      --surface: #FFFFFF;
      --muted: #5E6B73;
      --border: #D7DFE2;
      --soft: #F4F8F6;
      --radius: 12px;
      font-family: system-ui, sans-serif;
      font-size: 16px;
      color: var(--ink);
      background: var(--surface);
    }
    * { box-sizing: border-box; }
    body { margin: 0; }
    button { font: inherit; color: inherit; }
    .app { width: min(100%, 520px); margin: 0 auto; padding: 20px 16px 32px; }
    header { margin-bottom: 22px; }
    .brand { font-size: 14px; font-weight: 700; color: var(--muted); }
    h1 { font-size: 25px; line-height: 1.2; margin: 6px 0; }
    h2 { font-size: 20px; margin: 0 0 8px; }
    p { line-height: 1.5; }
    .muted, .hint { color: var(--muted); }
    .hint { font-size: 14px; margin: 6px 0 16px; }
    .steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin: 0 0 18px; }
    .step {
      min-height: 44px; padding: 8px 4px; border: 1px solid var(--border);
      border-radius: 8px; background: white; font-size: 12px; font-weight: 650;
    }
    .step[aria-current="step"] { border: 2px solid var(--ink); background: var(--soft); }
    .step:disabled { color: #4B555B; background: #F1F3F4; }
    .summary {
      border: 1px solid var(--border); border-radius: var(--radius);
      padding: 12px; margin-bottom: 20px; background: var(--soft);
    }
    .summary h2 { font-size: 16px; margin: 0 0 6px; }
    .summary p { margin: 3px 0; font-size: 14px; overflow-wrap: anywhere; }
    .card-list { display: grid; gap: 10px; }
    .choice {
      display: block; width: 100%; min-height: 58px; text-align: left;
      padding: 12px; border: 1px solid var(--border); border-radius: var(--radius);
      background: white; cursor: pointer;
    }
    .choice[aria-pressed="true"] { border: 2px solid var(--ink); background: var(--soft); }
    .choice:disabled { cursor: not-allowed; color: #4B555B; background: #F1F3F4; }
    .choice strong { display: block; margin-bottom: 3px; }
